    fn command_node_type(commands: &[BoardCommand], ref_id: &str) -> Option<String> {
        commands.iter().find_map(|command| match command {
            BoardCommand::AddNode {
                node_type,
                ref_id: Some(id),
                ..
            } if id == ref_id => Some(node_type.clone()),
            _ => None,
        })
    }

